                        currentRelease = updatedHistory.firstOrNull { r -> r.id == current.id }?.copy(status = "closed"),
                        releaseHistory = updatedHistory,
                        ownerProfile = updatedProfile ?: it.ownerProfile?.copy(credits = result.ownerCredits),

