package com.ntt.crosstest.ui.viewmodels

import android.app.Application
import com.ntt.crosstest.data.AppUpdateQuote
import com.ntt.crosstest.data.AppUpdateRelease
import com.ntt.crosstest.data.Campaign
import com.ntt.crosstest.data.CampaignDetailResult
import com.ntt.crosstest.data.CampaignRepository
import com.ntt.crosstest.data.FinancialIntentStore
import com.ntt.crosstest.data.Localizer
import com.ntt.crosstest.data.Profile
import com.ntt.crosstest.data.PublishAppUpdateResult
import com.ntt.crosstest.data.SessionCacheManager
import io.github.jan.supabase.SupabaseClient
import io.github.jan.supabase.createSupabaseClient
import io.github.jan.supabase.postgrest.Postgrest
import io.ktor.client.engine.mock.MockEngine
import io.ktor.client.engine.mock.respond
import kotlinx.coroutines.Dispatchers
import kotlinx.coroutines.ExperimentalCoroutinesApi
import kotlinx.coroutines.test.StandardTestDispatcher
import kotlinx.coroutines.test.advanceUntilIdle
import kotlinx.coroutines.test.resetMain
import kotlinx.coroutines.test.runTest
import kotlinx.coroutines.test.setMain
import org.junit.After
import org.junit.Assert.assertEquals
import org.junit.Assert.assertFalse
import org.junit.Assert.assertNotNull
import org.junit.Assert.assertNull
import org.junit.Assert.assertTrue
import org.junit.Before
import org.junit.Test
import org.junit.runner.RunWith
import org.robolectric.RobolectricTestRunner
import org.robolectric.RuntimeEnvironment
import org.robolectric.annotation.Config
import java.io.IOException

@OptIn(ExperimentalCoroutinesApi::class)
@RunWith(RobolectricTestRunner::class)
@Config(application = Application::class, sdk = [34])
class AppUpdateReleaseViewModelBehavioralTest {

    private val testDispatcher = StandardTestDispatcher()
    private lateinit var dummySupabase: SupabaseClient
    private lateinit var localizer: Localizer

    @Before
    fun setUp() {
        Dispatchers.setMain(testDispatcher)
        dummySupabase = createSupabaseClient("https://fixture.invalid", "dummy") {
            install(Postgrest)
            httpEngine = MockEngine { respond("{}") }
        }
        val context = RuntimeEnvironment.getApplication()
        localizer = Localizer(context)
    }

    @After
    fun tearDown() {
        Dispatchers.resetMain()
    }

    private class TestableCampaignRepository(
        supabase: SupabaseClient,
        localizer: Localizer,
    ) : CampaignRepository(supabase, localizer) {
        var currentUid: String? = "user-owner-1"
        var publishCallCount = 0
        var closeCallCount = 0
        var shouldThrowNetworkErrorOnPublish = false
        var shouldThrowConflictOnPublish = false
        var lastCapturedOperationId: String? = null
        var lastCapturedBudget: Int? = null
        var lastCapturedRevision: String? = null
        var lastCapturedExpectedReleaseId: String? = null

        override fun currentUserId(): String? = currentUid

        override suspend fun getCampaignDetailPage(campaignId: String, forceRefresh: Boolean): CampaignDetailResult {
            return CampaignDetailResult(
                campaign = Campaign(id = campaignId, ownerId = currentUid ?: ""),
                myProfile = Profile(id = currentUid ?: "", credits = 1000),
            )
        }

        override suspend fun getMyProfile(forceRefresh: Boolean): Profile {
            return Profile(id = currentUid ?: "", credits = 1000)
        }

        override suspend fun getCampaignUpdateHistory(campaignId: String): Result<List<AppUpdateRelease>> {
            return Result.success(emptyList())
        }

        override suspend fun getAppUpdateQuote(): AppUpdateQuote {
            return AppUpdateQuote(
                rewardPerClaim = 8,
                maxClaims = 25,
                reservedBudget = 200,
                revision = "quote-rev-token-200",
            )
        }

        override suspend fun publishAppUpdateV2(
            campaignId: String,
            versionName: String,
            targetVersionCode: Long,
            releaseNotes: String,
            clientOperationId: String,
            expectedBudget: Int?,
            expectedRevision: String?,
            expectedCurrentReleaseId: String?,
        ): Result<PublishAppUpdateResult> {
            publishCallCount++
            lastCapturedOperationId = clientOperationId
            lastCapturedBudget = expectedBudget
            lastCapturedRevision = expectedRevision
            lastCapturedExpectedReleaseId = expectedCurrentReleaseId

            if (shouldThrowNetworkErrorOnPublish) {
                return Result.failure(IOException("Socket timeout simulating network loss"))
            }
            if (shouldThrowConflictOnPublish) {
                return Result.failure(Exception("BUSINESS_POLICY_CONFLICT: Revision changed"))
            }

            return Result.success(
                PublishAppUpdateResult(
                    success = true,
                    ownerCredits = 800,
                    release = AppUpdateRelease(
                        id = "rel-created-1",
                        campaignId = campaignId,
                        versionName = versionName,
                        targetVersionCode = targetVersionCode,
                        releaseNotes = releaseNotes,
                        rewardPerClaim = 8,
                        maxClaims = 25,
                        reservedCredits = 200,
                        status = "active",
                    )
                )
            )
        }

        override suspend fun closeAppUpdateRelease(
            releaseId: String,
            reason: String,
            campaignId: String?,
        ): Result<com.ntt.crosstest.data.CloseAppUpdateReleaseResult> {
            closeCallCount++
            return Result.success(
                com.ntt.crosstest.data.CloseAppUpdateReleaseResult(
                    success = true,
                    refundAmount = 200,
                )
            )
        }
    }

    @Test
    fun lostResponse_persistsIntentToDisk_recreationReusesOriginalOperationIdAndQuote() = runTest {
        val context = RuntimeEnvironment.getApplication()
        val repo = TestableCampaignRepository(dummySupabase, localizer)
        FinancialIntentStore.clearAllPublishIntentsForUser(context, "user-owner-1")

        val vm1 = AppUpdateReleaseViewModel("camp-1", repo, localizer)
        advanceUntilIdle()

        vm1.onVersionNameChange("2.0.0")
        vm1.onVersionCodeChange("20")
        vm1.onReleaseNotesChange("Bug fixes and speed")
        assertTrue(vm1.uiState.value.canPublish)

        // Simulate network loss on first publish
        repo.shouldThrowNetworkErrorOnPublish = true
        vm1.publishUpdate()
        advanceUntilIdle()

        // 1. Error shown, but intent is committed to disk store
        assertNotNull(vm1.uiState.value.error)
        val diskIntent = FinancialIntentStore.peekPublishIntent(context, "user-owner-1", "camp-1")
        assertNotNull(diskIntent)
        assertEquals("2.0.0", diskIntent!!.versionName)
        assertEquals(20L, diskIntent.targetVersionCode)
        assertEquals(200, diskIntent.expectedBudget)
        assertEquals("quote-rev-token-200", diskIntent.expectedRevision)
        assertNull(diskIntent.expectedCurrentReleaseId) // Exact NULL preserved!
        val originalOperationId = diskIntent.clientOperationId
        assertNotNull(originalOperationId)

        // 2. Simulate process death / ViewModel recreation
        val vm2 = AppUpdateReleaseViewModel("camp-1", repo, localizer)
        advanceUntilIdle()

        // The recreated VM restores the pending intent
        val restoredPending = vm2.uiState.value.pendingPublishIntent
        assertNotNull(restoredPending)
        assertEquals(originalOperationId, restoredPending!!.clientOperationId)

        // 3. Retry sends the EXACT original operation ID and quote revision!
        repo.shouldThrowNetworkErrorOnPublish = false
        vm2.retryPendingPublish()
        advanceUntilIdle()

        assertEquals(originalOperationId, repo.lastCapturedOperationId)
        assertEquals("quote-rev-token-200", repo.lastCapturedRevision)
        assertEquals(200, repo.lastCapturedBudget)
        assertNull(repo.lastCapturedExpectedReleaseId)

        // 4. Upon success, intent is cleared from disk!
        assertNull(FinancialIntentStore.peekPublishIntent(context, "user-owner-1", "camp-1"))
        assertNull(vm2.uiState.value.pendingPublishIntent)
    }

    @Test
    fun atomicPublishVsCloseGate_preventsConcurrentExecution() = runTest {
        val repo = TestableCampaignRepository(dummySupabase, localizer)
        val vm = AppUpdateReleaseViewModel("camp-1", repo, localizer)
        advanceUntilIdle()

        vm.onVersionNameChange("2.1.0")
        vm.onVersionCodeChange("21")
        vm.onReleaseNotesChange("Notes")

        // Trigger publish
        vm.publishUpdate()
        // Concurrent close must be gated and dropped
        vm.closeCurrentRelease()
        advanceUntilIdle()

        assertEquals(1, repo.publishCallCount)
        assertEquals(0, repo.closeCallCount)
    }

    @Test
    fun changedQuoteConflict_clearsDiskIntentAndPromptsReconfirm() = runTest {
        val context = RuntimeEnvironment.getApplication()
        val repo = TestableCampaignRepository(dummySupabase, localizer)
        FinancialIntentStore.clearAllPublishIntentsForUser(context, "user-owner-1")

        val vm = AppUpdateReleaseViewModel("camp-1", repo, localizer)
        advanceUntilIdle()

        vm.onVersionNameChange("2.2.0")
        vm.onVersionCodeChange("22")
        vm.onReleaseNotesChange("Notes")

        repo.shouldThrowConflictOnPublish = true
        vm.publishUpdate()
        advanceUntilIdle()

        // On conflict: disk intent must be cleared, not retrying with stale quote
        assertNull(FinancialIntentStore.peekPublishIntent(context, "user-owner-1", "camp-1"))
        assertNotNull(vm.uiState.value.error)
    }
}

package com.ntt.crosstest.ui.viewmodels

import android.app.Application
import com.ntt.crosstest.data.AuthRepository
import com.ntt.crosstest.data.Campaign
import com.ntt.crosstest.data.CampaignDetailResult
import com.ntt.crosstest.data.CampaignPushStore
import com.ntt.crosstest.data.CampaignRepository
import com.ntt.crosstest.data.FinancialIntentStore
import com.ntt.crosstest.data.Localizer
import com.ntt.crosstest.data.PendingSlotIntent
import com.ntt.crosstest.data.Profile
import com.ntt.crosstest.data.PushCampaignResult
import com.ntt.crosstest.data.PushQuote
import com.ntt.crosstest.data.SlotInfo
import com.ntt.crosstest.data.UnlockSlotResult
import com.ntt.crosstest.data.UserSlot
import io.github.jan.supabase.SupabaseClient
import io.github.jan.supabase.createSupabaseClient
import io.github.jan.supabase.postgrest.Postgrest
import io.ktor.client.engine.mock.MockEngine
import io.ktor.client.engine.mock.respond
import kotlinx.coroutines.Dispatchers
import kotlinx.coroutines.ExperimentalCoroutinesApi
import kotlinx.coroutines.test.StandardTestDispatcher
import kotlinx.coroutines.test.advanceUntilIdle
import kotlinx.coroutines.test.resetMain
import kotlinx.coroutines.test.runTest
import kotlinx.coroutines.test.setMain
import org.junit.After
import org.junit.Assert.assertEquals
import org.junit.Assert.assertFalse
import org.junit.Assert.assertNotNull
import org.junit.Assert.assertNull
import org.junit.Assert.assertTrue
import org.junit.Before
import org.junit.Test
import org.junit.runner.RunWith
import org.robolectric.RobolectricTestRunner
import org.robolectric.RuntimeEnvironment
import org.robolectric.annotation.Config
import java.io.IOException

@OptIn(ExperimentalCoroutinesApi::class)
@RunWith(RobolectricTestRunner::class)
@Config(application = Application::class, sdk = [34])
class SlotAndPushDurabilityBehavioralTest {

    private val testDispatcher = StandardTestDispatcher()
    private lateinit var dummySupabase: SupabaseClient
    private lateinit var localizer: Localizer
    private lateinit var authRepository: AuthRepository

    @Before
    fun setUp() {
        Dispatchers.setMain(testDispatcher)
        dummySupabase = createSupabaseClient("https://fixture.invalid", "dummy") {
            install(Postgrest)
            httpEngine = MockEngine { respond("{}") }
        }
        val context = RuntimeEnvironment.getApplication()
        localizer = Localizer(context)
        authRepository = AuthRepository(dummySupabase, context)
    }

    @After
    fun tearDown() {
        Dispatchers.resetMain()
    }

    private class TestableSlotRepository(
        supabase: SupabaseClient,
        localizer: Localizer,
    ) : CampaignRepository(supabase, localizer) {
        var currentUid: String? = "user-slot-owner"
        var unlockCallCount = 0
        var pushCallCount = 0
        var shouldThrowNetworkError = false
        var lastCapturedSlotRequestId: String? = null
        var lastCapturedPushRequestId: String? = null

        override fun currentUserId(): String? = currentUid

        override suspend fun getCampaignDetailPage(campaignId: String, forceRefresh: Boolean): CampaignDetailResult {
            return CampaignDetailResult(
                campaign = Campaign(id = campaignId, ownerId = currentUid ?: "", slotNumber = 2),
                myProfile = Profile(id = currentUid ?: "", credits = 1000),
            )
        }

        override suspend fun getMyProfile(forceRefresh: Boolean): Profile {
            return Profile(id = currentUid ?: "", credits = 1000)
        }

        override suspend fun getPushQuote(): PushQuote {
            return PushQuote(quoteType = "push", cost = 100, revision = "push-token-1")
        }

        override suspend fun getMySlotsInfo(forceRefresh: Boolean): List<SlotInfo> {
            return listOf(
                SlotInfo(slotNumber = 1, isPermanent = true, isUnlocked = true),
                SlotInfo(
                    slotNumber = 2,
                    isUnlocked = true,
                    isExpired = false,
                    cost = 50,
                    renewalDays = 30,
                    policyRevision = "slot-token-2"
                )
            )
        }

        override suspend fun unlockOrRenewSlotV2(
            slotNumber: Int,
            clientRequestId: String,
            expectedCost: Int?,
            expectedRevision: String?,
        ): UnlockSlotResult {
            unlockCallCount++
            lastCapturedSlotRequestId = clientRequestId

            if (shouldThrowNetworkError) {
                throw IOException("Network loss on slot purchase")
            }

            return UnlockSlotResult(
                success = true,
                slotNumber = slotNumber,
                cost = expectedCost ?: 50,
                balance = 950,
                clientRequestId = clientRequestId,
                renewalDays = 30,
            )
        }

        override suspend fun pushCampaignV2(
            campaignId: String,
            clientRequestId: String,
            expectedCost: Int?,
            expectedRevision: String?,
        ): PushCampaignResult {
            pushCallCount++
            lastCapturedPushRequestId = clientRequestId

            if (shouldThrowNetworkError) {
                throw IOException("Network loss on push")
            }

            return PushCampaignResult(
                success = true,
                chargedCredits = expectedCost ?: 100,
                balanceAfter = 900,
                clientRequestId = clientRequestId,
            )
        }
    }

    @Test
    fun renewCurrentSlot_lostReply_retryReusesSameUUIDAndOriginalQuote() = runTest {
        val context = RuntimeEnvironment.getApplication()
        val repo = TestableSlotRepository(dummySupabase, localizer)
        FinancialIntentStore.clearAllSlotIntentsForUser(context, "user-slot-owner")

        val vm = OwnerAppDetailViewModel("camp-1", repo, localizer)
        advanceUntilIdle()

        // 1. First renew attempt fails with network loss
        repo.shouldThrowNetworkError = true
        vm.renewCurrentSlot()
        advanceUntilIdle()

        assertNotNull(vm.uiState.value.error)
        val savedIntent = FinancialIntentStore.peekSlotIntent(context, "user-slot-owner", 2)
        assertNotNull(savedIntent)
        assertEquals(50, savedIntent!!.expectedCost)
        assertEquals("slot-token-2", savedIntent.expectedRevision)
        val originalRequestId = savedIntent.clientRequestId
        assertNotNull(originalRequestId)
        assertEquals(originalRequestId, repo.lastCapturedSlotRequestId)

        // 2. Retry renew reuses the EXACT stored clientRequestId from FinancialIntentStore!
        repo.shouldThrowNetworkError = false
        vm.renewCurrentSlot()
        advanceUntilIdle()

        assertEquals(2, repo.unlockCallCount)
        assertEquals(originalRequestId, repo.lastCapturedSlotRequestId)

        // 3. Upon success, intent is cleared from disk
        assertNull(FinancialIntentStore.peekSlotIntent(context, "user-slot-owner", 2))
    }

    @Test
    fun accountSwitch_slotIntentIsolation() {
        val context = RuntimeEnvironment.getApplication()
        FinancialIntentStore.clearAllSlotIntentsForUser(context, "user-A")
        FinancialIntentStore.clearAllSlotIntentsForUser(context, "user-B")

        val intentA = PendingSlotIntent(
            userId = "user-A",
            slotNumber = 2,
            expectedCost = 50,
            expectedRevision = "rev-A",
            renewalDays = 30,
            clientRequestId = "req-A-1",
        )
        FinancialIntentStore.saveSlotIntent(context, intentA)

        // User A sees its own intent
        val retrievedA = FinancialIntentStore.peekSlotIntent(context, "user-A", 2)
        assertNotNull(retrievedA)
        assertEquals("req-A-1", retrievedA!!.clientRequestId)

        // User B sees NOTHING of User A's intent!
        val retrievedB = FinancialIntentStore.peekSlotIntent(context, "user-B", 2)
        assertNull(retrievedB)
    }

    @Test
    fun pushApp_lostReply_preservesCampaignPushStoreRequestId() = runTest {
        val context = RuntimeEnvironment.getApplication()
        val repo = TestableSlotRepository(dummySupabase, localizer)
        CampaignPushStore.clearPendingRequestId(context, "user-slot-owner", "camp-1")

        val vm = OwnerAppDetailViewModel("camp-1", repo, localizer)
        advanceUntilIdle()

        repo.shouldThrowNetworkError = true
        vm.pushApp(context)
        advanceUntilIdle()

        // Push failed due to network loss, pending request ID must be preserved in store
        val pendingId = CampaignPushStore.peekPendingRequestId(context, "user-slot-owner", "camp-1")
        assertNotNull(pendingId)
        assertEquals(pendingId, repo.lastCapturedPushRequestId)

        // Retry reuses the exact same request ID
        repo.shouldThrowNetworkError = false
        vm.retryOriginalPurchase(context)
        advanceUntilIdle()

        assertEquals(2, repo.pushCallCount)
        assertEquals(pendingId, repo.lastCapturedPushRequestId)

        // On success, store is cleared
        assertNull(CampaignPushStore.peekPendingRequestId(context, "user-slot-owner", "camp-1"))
    }

    @Test
    fun profileSlot_quoteUnavailable_blocksPurchase() = runTest {
        val repo = TestableSlotRepository(dummySupabase, localizer)
        val app = contextApplication()
        val vm = ProfileViewModel(authRepository, repo, app)
        advanceUntilIdle()

        // Attempting to unlock with null revision must be blocked
        vm.unlockOrRenewSlot(slotNumber = 2, expectedCost = 50, expectedRevision = null)
        advanceUntilIdle()

        assertNotNull(vm.uiState.value.error)
        assertEquals(0, repo.unlockCallCount)
    }

    private fun contextApplication(): com.ntt.crosstest.TestCheoApp {
        return RuntimeEnvironment.getApplication() as com.ntt.crosstest.TestCheoApp
    }
}
